/**
 * POST /api/contact — the "Start a conversation" form (src/components/contact/ContactForm.astro and the chat
 * widget's inline form). Vercel Function, Node runtime, Web-standard handler.
 *
 * Accepts JSON, multipart or urlencoded with the src/data/contact.ts field names (CONTACT_FIELDS with their maxLength
 * caps, generated by scripts/build-knowledge.mjs), plus:
 *   company_website  honeypot: filled → { ok: true } and nothing is sent
 *   started_at       time trap: ms timestamp of page load; missing, or sent < 3 s after it → { ok: true }, nothing sent
 *   chat_transcript  optional, from the chat widget: the questions and answers so far (capped)
 * Server-side checks: required fields, email format, length caps, select options, consent; per-IP rate limit
 * (5 per 10 minutes, in memory, best effort); same-origin guard.
 *
 * Delivery:
 *   RESEND_API_KEY set → Resend REST API (https://api.resend.com/emails): the enquiry to CONTACT_TO
 *     (default office@kokreaters.com, comma-separated list allowed) from RESEND_FROM (default
 *     "KoKreaters website <website@kokreaters.com>"), reply_to = the visitor; then a short confirmation to the visitor
 *     (fixed copy, no visitor-supplied text in it; CONTACT_CONFIRMATION=0 turns it off).
 *   Resend error (e.g. domain not verified yet) → the same enquiry goes through FormSubmit instead
 *     (CONTACT_FORMSUBMIT_FALLBACK=0 turns that off).
 *   no RESEND_API_KEY → forwarded to FormSubmit (https://formsubmit.co/ajax/<CONTACT_TO>) as JSON, so mail flows today.
 *   CONTACT_DRY_RUN=1 → validate and log only; nothing is sent (local tests).
 * Responses: 200 { ok: true } · 400 { ok: false, error: 'invalid', fields: { name: 'required' | 'email' | 'length' | 'option' } }
 *            · 403 origin · 413 too large · 429 rate limited · 502 delivery failed.
 */
import { CONTACT_FIELDS, CONTACT_EMAIL } from './_lib/knowledge.js';
import { json, methodNotAllowed, clientIp, originAllowed, rateLimiter, readBody, parseFields, escapeHtml } from './_lib/http.js';

const MAX_BODY = 32 * 1024;
const MIN_MS = 3000;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const TRANSCRIPT_CAP = 8000;
const CONFIRMATION = 'Thank you for getting in touch with KoKreaters. We have received your message and will reply by email.';
const limit = rateLimiter({ limit: 5, windowMs: 10 * 60 * 1000 });

const clean = (v) => String(v ?? '').replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
const oneLine = (v) => clean(v).replace(/\s+/g, ' ');

/** Validate against CONTACT_FIELDS. Returns { values, errors }. */
export function validate(input) {
  const values = {};
  const errors = {};
  for (const f of CONTACT_FIELDS) {
    if (f.type === 'checkbox') {
      const v = String(input[f.name] ?? '').toLowerCase();
      const on = input[f.name] === true || ['yes', 'on', 'true', '1'].includes(v);
      values[f.name] = on;
      if (f.required && !on) errors[f.name] = 'required';
      continue;
    }
    const v = f.type === 'textarea' ? clean(input[f.name]) : oneLine(input[f.name]);
    values[f.name] = v;
    if (f.required && !v) { errors[f.name] = 'required'; continue; }
    if (v.length > (f.maxLength ?? 500)) { errors[f.name] = 'length'; continue; }
    if (f.type === 'email' && v && !EMAIL_RE.test(v)) { errors[f.name] = 'email'; continue; }
    if (f.type === 'select' && v && f.options && !f.options.includes(v)) errors[f.name] = 'option';
  }
  const transcript = clean(input.chat_transcript);
  values.chat_transcript = transcript.length > TRANSCRIPT_CAP ? `${transcript.slice(0, TRANSCRIPT_CAP)}\n[…]` : transcript;
  return { values, errors };
}

const recipients = () => (process.env.CONTACT_TO || CONTACT_EMAIL || 'office@kokreaters.com').split(',').map((s) => s.trim()).filter(Boolean);
const sender = () => process.env.RESEND_FROM || 'KoKreaters website <website@kokreaters.com>';
const subjectFor = (v) => `New enquiry: ${v.name}, ${v.company}`.replace(/[\r\n]+/g, ' ').slice(0, 200);
const rows = (v) => [
  ...CONTACT_FIELDS.map((f) => [f.type === 'checkbox' ? 'Consent to store details' : f.label, f.type === 'checkbox' ? (v[f.name] ? 'Yes' : 'No') : v[f.name] || '']),
  ...(v.chat_transcript ? [['Chat transcript', v.chat_transcript]] : []),
];

export function enquiryEmail(v, meta = {}) {
  const r = rows(v);
  const text = [
    `New enquiry from the KoKreaters website${meta.via === 'chat' ? ' (via Ask KoKreaters)' : ''}`,
    '',
    ...r.map(([k, val]) => (val.includes('\n') ? `${k}:\n${val}\n` : `${k}: ${val}`)),
    '',
    meta.page ? `Sent from: ${meta.page}` : '',
    'Reply to this email to answer the visitor directly.',
  ].filter((l, i, a) => l !== '' || a[i - 1] !== '').join('\n');
  const cell = 'padding:10px 14px;border-bottom:1px solid #D9D9D4;vertical-align:top;font:15px/1.5 Arial,Helvetica,sans-serif;';
  const html = `<!doctype html><html><body style="margin:0;padding:24px;background:#F2F2F0;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:680px;margin:0 auto;background:#FFFFFF;border-collapse:collapse;">
<tr><td colspan="2" style="padding:20px 14px;background:#0B1B33;color:#FFFFFF;font:600 18px/1.3 Georgia,'Times New Roman',serif;">New enquiry from the KoKreaters website${meta.via === 'chat' ? ' <span style="font:400 13px Arial,sans-serif;color:#C2C6CC;">via Ask KoKreaters</span>' : ''}</td></tr>
${r.map(([k, val]) => `<tr><th align="left" style="${cell}width:30%;color:#5A5A5A;font-weight:600;">${escapeHtml(k)}</th><td style="${cell}color:#1A1A1A;white-space:pre-wrap;">${escapeHtml(val) || '<span style="color:#8A8A85;">(not given)</span>'}</td></tr>`).join('\n')}
<tr><td colspan="2" style="padding:14px;font:13px/1.5 Arial,sans-serif;color:#5A5A5A;">${meta.page ? `Sent from ${escapeHtml(meta.page)}. ` : ''}Reply to this email to answer ${escapeHtml(v.name)} directly.</td></tr>
</table></body></html>`;
  return { subject: subjectFor(v), text, html };
}

export function confirmationEmail() {
  const text = `${CONFIRMATION}\n\nKoKreaters\nConnect · Collaborate · Create\nhttps://kokreaters.com`;
  const html = `<!doctype html><html><body style="margin:0;padding:24px;background:#F2F2F0;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto;background:#FFFFFF;border-collapse:collapse;">
<tr><td style="padding:22px 28px;background:#0B1B33;color:#FFFFFF;font:600 20px/1.2 Georgia,'Times New Roman',serif;">KoKreaters</td></tr>
<tr><td style="padding:28px 28px 8px;font:17px/1.6 Arial,Helvetica,sans-serif;color:#1A1A1A;">${escapeHtml(CONFIRMATION)}</td></tr>
<tr><td style="padding:16px 28px 28px;font:14px/1.5 Arial,Helvetica,sans-serif;color:#5A5A5A;">KoKreaters · Connect · Collaborate · Create<br><a href="https://kokreaters.com" style="color:#2C509E;">kokreaters.com</a></td></tr>
</table></body></html>`;
  return { subject: 'Thank you for contacting KoKreaters', text, html };
}

async function resendSend(payload) {
  const res = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${process.env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`resend ${res.status}: ${(await res.text()).slice(0, 300)}`);
  return res.json().catch(() => ({}));
}

async function viaResend(v, meta) {
  const mail = enquiryEmail(v, meta);
  await resendSend({ from: sender(), to: recipients(), reply_to: v.email, subject: mail.subject, text: mail.text, html: mail.html });
  if (process.env.CONTACT_CONFIRMATION !== '0') {
    const c = confirmationEmail();
    try {
      await resendSend({ from: sender(), to: [v.email], reply_to: recipients()[0], subject: c.subject, text: c.text, html: c.html });
    } catch (e) {
      console.error('contact: confirmation failed', e.message);   // the enquiry itself went through
    }
  }
}

async function viaFormSubmit(v, meta, request) {
  const to = recipients()[0];
  const body = {};
  for (const [k, val] of rows(v)) body[k] = val;
  Object.assign(body, {
    _subject: subjectFor(v), _template: 'table', _captcha: 'false', _replyto: v.email, _autoresponse: CONFIRMATION,
  });
  // FormSubmit only accepts submissions that name the page they came from.
  const origin = request.headers.get('origin') || 'https://kokreaters.com';
  const res = await fetch(`https://formsubmit.co/ajax/${encodeURIComponent(to)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json', Origin: origin, Referer: meta.page || `${origin}/contact` },
    body: JSON.stringify(body),
  });
  const out = await res.json().catch(() => ({}));
  if (!res.ok || String(out.success) !== 'true') throw new Error(`formsubmit ${res.status}: ${JSON.stringify(out).slice(0, 300)}`);
}

export async function POST(request) {
  if (!originAllowed(request)) return json(403, { ok: false, error: 'origin' });
  const ip = clientIp(request);
  const rl = limit(ip);
  if (!rl.ok) return json(429, { ok: false, error: 'rate_limited' }, { 'Retry-After': String(rl.retryAfter) });

  const text = await readBody(request, MAX_BODY);
  if (text === null) return json(413, { ok: false, error: 'too_large' });
  let input;
  try { input = await parseFields(request, text); } catch { return json(400, { ok: false, error: 'bad_body' }); }

  // honeypot / time trap: look successful, send nothing
  if (String(input.company_website ?? '').trim() !== '') return json(200, { ok: true });
  const started = Number(input.started_at);
  const elapsed = Date.now() - started;
  if (!Number.isFinite(started) || started <= 0 || (elapsed >= 0 && elapsed < MIN_MS)) return json(200, { ok: true });

  const { values, errors } = validate(input);
  if (Object.keys(errors).length) return json(400, { ok: false, error: 'invalid', fields: errors });

  const meta = { via: input.via === 'chat' ? 'chat' : 'form', page: oneLine(input.page_url || request.headers.get('referer') || '').slice(0, 300) };
  try {
    if (process.env.CONTACT_DRY_RUN === '1') console.log('contact: dry run', JSON.stringify({ ...values, message: `${values.message.length} chars` }));
    else if (process.env.RESEND_API_KEY) {
      try { await viaResend(values, meta); }
      catch (e) {
        // e.g. the sending domain is not verified in Resend yet: the enquiry still reaches office@ through FormSubmit
        console.error('contact: resend failed, falling back to FormSubmit', e.message);
        if (process.env.CONTACT_FORMSUBMIT_FALLBACK === '0') throw e;
        await viaFormSubmit(values, meta, request);
      }
    } else await viaFormSubmit(values, meta, request);
  } catch (e) {
    console.error('contact: delivery failed', e.message);
    return json(502, { ok: false, error: 'delivery' });
  }
  return json(200, { ok: true });
}

export const GET = methodNotAllowed;
